    "Form1.gbas": "' Benchmark 4 (STAGE2_PLAN §7): a small game. 20 Images move a little\n' every round, every pair is checked for a collision, and the score\n' Label changes. With no Timer yet, DoEvents ends each round, as a 30 ms\n' Timer's Tick would.\nDim x(19) As Integer\nDim y(19) As Integer\nDim dx(19) As Integer\nDim dy(19) As Integer\nDim score As Integer\n\nSub Form_Load()\n    Dim i As Integer\n    For i = 0 To 19\n        x(i) = 20 + (i Mod 5) * 70\n        y(i) = 60 + (i \\ 5) * 70\n        dx(i) = 1 + i Mod 3\n        dy(i) = 1 + i Mod 2\n        If i Mod 2 = 0 Then\n            dy(i) = -dy(i)\n        End If\n    Next\nEnd Sub\n\nSub btnStart_Click()\n    Debug.Print(\"bench:start\")\n    Dim r As Integer\n    Dim i As Integer\n    Dim j As Integer\n    For r = 1 To 300\n        For i = 0 To 19\n            x(i) = x(i) + dx(i)\n            y(i) = y(i) + dy(i)\n            If x(i) < 0 Or x(i) > 384 Then\n                dx(i) = -dx(i)\n            End If\n            If y(i) < 48 Or y(i) > 384 Then\n                dy(i) = -dy(i)\n            End If\n        Next\n        For i = 0 To 18\n            For j = i + 1 To 19\n                If Abs(x(i) - x(j)) < 16 And Abs(y(i) - y(j)) < 16 Then\n                    score = score + 1\n                End If\n            Next\n        Next\n        img1.Left = x(0)\n        img1.Top = y(0)\n        img2.Left = x(1)\n        img2.Top = y(1)\n        img3.Left = x(2)\n        img3.Top = y(2)\n        img4.Left = x(3)\n        img4.Top = y(3)\n        img5.Left = x(4)\n        img5.Top = y(4)\n        img6.Left = x(5)\n        img6.Top = y(5)\n        img7.Left = x(6)\n        img7.Top = y(6)\n        img8.Left = x(7)\n        img8.Top = y(7)\n        img9.Left = x(8)\n        img9.Top = y(8)\n        img10.Left = x(9)\n        img10.Top = y(9)\n        img11.Left = x(10)\n        img11.Top = y(10)\n        img12.Left = x(11)\n        img12.Top = y(11)\n        img13.Left = x(12)\n        img13.Top = y(12)\n        img14.Left = x(13)\n        img14.Top = y(13)\n        img15.Left = x(14)\n        img15.Top = y(14)\n        img16.Left = x(15)\n        img16.Top = y(15)\n        img17.Left = x(16)\n        img17.Top = y(16)\n        img18.Left = x(17)\n        img18.Top = y(17)\n        img19.Left = x(18)\n        img19.Top = y(18)\n        img20.Left = x(19)\n        img20.Top = y(19)\n        lblScore.Caption = \"Score: \" & score\n        DoEvents\n    Next\n    Debug.Print(\"bench:end \" & score)\nEnd Sub\n",
    "Game.gbproj": "formatVersion: 1\nname: Game\nstartup: Form1\nforms:\n  - Form1\npictures:\n  - ball.png\n",
  },
  "loop": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Loop\n  Width: 320\n  Height: 120\ncontrols:\n  - name: btnStart\n    type: Button\n    properties:\n      Caption: Start\n      Left: 8\n      Top: 8\n      Width: 96\n",
    "Form1.gbas": "' Benchmark 1 (STAGE2_PLAN §7): a million rounds of arithmetic.\nSub btnStart_Click()\n    Debug.Print(\"bench:start\")\n    Dim total As Integer = 0\n    Dim i As Integer\n    For i = 1 To 1000000\n        total = total + i * 2 - 1\n    Next\n    Debug.Print(\"bench:end \" & total)\nEnd Sub\n",
    "Loop.gbproj":
        "formatVersion: 1\nname: Loop\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "quiz": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 퀴즈\n  Width: 400\n  Height: 300\ncontrols:\n  - name: lblNumber\n    type: Label\n    properties:\n      Left: 16\n      Top: 12\n      Width: 368\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 40\n      Width: 368\n  - name: lstChoices\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 72\n      Width: 232\n      Height: 116\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 264\n      Top: 72\n      Width: 120\n      Height: 116\n  - name: chkShowAnswer\n    type: CheckBox\n    properties:\n      Caption: 틀리면 정답 보여 주기\n      Left: 16\n      Top: 200\n      Width: 240\n  - name: btnCheck\n    type: Button\n    properties:\n      Caption: 정답 확인\n      Left: 16\n      Top: 248\n      Width: 136\n  - name: lblScore\n    type: Label\n    properties:\n      Left: 168\n      Top: 252\n      Width: 216\n",
    "Form1.gbas": "' 작은 퀴즈: 문제를 보여 주고, ListBox의 보기 가운데 하나를 고르면\n' 맞았는지 알려 주며 점수를 셉니다. 최고 점수는 저장해 두었다가 다음에\n' 실행할 때도 보여 줍니다. 그림 문제는 프로젝트의 그림(pictures 폴더)을\n' Image에 보여 줍니다.\n\n' 문제 하나에 딸린 것을 한 이름으로 묶습니다(Structure).\nStructure Question\n    Text As String\n    Choices(3) As String    ' 보기 네 개\n    Answer As Integer       ' 정답 보기의 번호(0부터)\n    Picture As String       ' 문제의 그림 이름. 그림이 없는 문제는 \"\"\nEnd Structure\n\nDim questions(6) As Question\nDim current As Integer\nDim score As Integer\nDim best As Integer\n\nSub Form_Load()\n    ' New … With { }로 문제 하나를 한 번에 만듭니다. 보기는 { }로 적은 배열입니다.\n    questions(0) = New Question With {.Text = \"대한민국의 수도는 어디일까요?\",\n                                      .Choices = {\"부산\", \"서울\", \"대구\", \"인천\"}, .Answer = 1}\n    questions(1) = New Question With {.Text = \"윤년이 아닌 해는 며칠일까요?\",\n                                      .Choices = {\"360일\", \"365일\", \"366일\", \"370일\"}, .Answer = 1}\n    questions(2) = New Question With {.Text = \"1기압에서 물이 끓는 온도는?\",\n                                      .Choices = {\"50도\", \"80도\", \"100도\", \"120도\"}, .Answer = 2}\n    questions(3) = New Question With {.Text = \"세종대왕이 만든 글자는?\",\n                                      .Choices = {\"한자\", \"한글\", \"가나\", \"알파벳\"}, .Answer = 1}\n    questions(4) = New Question With {.Text = \"7 × 8은 얼마일까요?\",\n                                      .Choices = {\"54\", \"56\", \"58\", \"64\"}, .Answer = 1}\n    questions(5) = New Question With {.Text = \"이 도형의 이름은?\",\n                                      .Choices = {\"사각형\", \"원\", \"삼각형\", \"오각형\"}, .Answer = 2,\n                                      .Picture = \"triangle.png\"}\n    questions(6) = New Question With {.Text = \"이 도형의 꼭짓점은 몇 개일까요?\",\n                                      .Choices = {\"4개\", \"5개\", \"6개\", \"8개\"}, .Answer = 1,\n                                      .Picture = \"pentagon.png\"}\n    ' 지난 실행까지의 최고 점수. 저장된 것이 없으면 \"0\"입니다.\n    best = CInt(GetSetting(\"best\", \"0\"))\n    ShowQuestion(0)\nEnd Sub\n\nSub ShowQuestion(number As Integer)\n    current = number\n    Dim q As Question = questions(number)\n    lblNumber.Caption = \"문제 \" & (number + 1) & \" / \" & (UBound(questions) + 1)\n    lblQuestion.Caption = q.Text\n    ' 그림 이름을 넣으면 그 그림을, \"\"을 넣으면 아무것도 보여 주지 않습니다.\n    imgQuestion.Picture = q.Picture\n    ' Clear()는 고른 항목도 지웁니다. 그래서 고른 것이 있었다면\n    ' lstChoices_Changed가 실행되고, ListIndex는 -1(고른 것 없음)이 됩니다.\n    lstChoices.Clear()\n    For Each choice In q.Choices\n        lstChoices.AddItem(choice)\n    Next\n    lblScore.Caption = \"점수: \" & score & \" · 최고 점수: \" & best\nEnd Sub\n\nSub lstChoices_Changed()\n    ' ListIndex가 바뀔 때마다 실행됩니다: 보기를 고를 때, 그리고 Clear()로\n    ' 고른 것이 없어질 때(ListIndex = -1).\n    If lstChoices.ListIndex = -1 Then\n        btnCheck.Caption = \"정답 확인\"\n    Else\n        btnCheck.Caption = \"확인: \" & lstChoices.Text\n    End If\nEnd Sub\n\nSub btnCheck_Click()\n    If lstChoices.ListIndex = -1 Then\n        MsgBox(\"먼저 보기를 하나 고르세요.\")\n        Exit Sub\n    End If\n    If lstChoices.ListIndex = questions(current).Answer Then\n        score = score + 1\n        MsgBox(\"정답입니다!\")\n    ElseIf chkShowAnswer.Checked Then\n        MsgBox(\"틀렸습니다. 정답: \" & lstChoices.List(questions(current).Answer))\n    Else\n        MsgBox(\"틀렸습니다.\")\n    End If\n    If current < UBound(questions) Then\n        ShowQuestion(current + 1)\n    Else\n        Dim message As String = (UBound(questions) + 1) & \"문제 가운데 \" & score & \"문제를 맞혔습니다.\"\n        If score > best Then\n            ' SaveSetting으로 저장한 값은 프로그램을 다시 실행해도 남습니다.\n            best = score\n            SaveSetting(\"best\", best)\n            message = message & \" 새 최고 점수입니다!\"\n        End If\n        MsgBox(message & \" 처음부터 다시 합니다.\")\n        score = 0\n        ShowQuestion(0)\n    End If\nEnd Sub\n",
    "Quiz.gbproj": "formatVersion: 2\nname: Quiz\nstartup: Form1\nforms:\n  - Form1\npictures:\n  - triangle.png\n  - pentagon.png\n",
  },
  "shooter": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Shooter\n  Width: 480\n  Height: 640\n  BackColor: \"#0B1026\"\ncontrols:\n  - name: lblScore\n    type: Label\n    properties:\n      Caption: 점수 0\n      Left: 12\n      Top: 8\n      Width: 160\n      Height: 24\n      FontSize: 14.0\n      FontBold: true\n      ForeColor: White\n  - name: lblLives\n    type: Label\n    properties:\n      Caption: 목숨 3\n      Left: 308\n      Top: 8\n      Width: 160\n      Height: 24\n      FontSize: 14.0\n      FontBold: true\n      ForeColor: White\n      Anchor: Right Top\n  - name: lblMessage\n    type: Label\n    properties:\n      Caption: 시작을 누르세요\n      Left: 40\n      Top: 260\n      Width: 400\n      Height: 40\n      FontSize: 22.0\n      FontBold: true\n      ForeColor: Gold\n  - name: btnStart\n    type: Button\n    properties:\n      Caption: 시작\n      Left: 180\n      Top: 592\n      Width: 120\n      Height: 36\n      Anchor: Left Bottom\n  - name: sprShip\n    type: Sprite\n    properties:\n      Frames: ship.png\n      Shape: Rectangle\n      Left: 224\n      Top: 540\n      Width: 32\n      Height: 32\n  - name: tmrGame\n    type: Timer\n    properties:\n      Interval: 16\n",
    "Form1.gbas": "' 슈팅 게임의 정석(docs/DESIGN.md D138): Timer 하나가 게임 루프이고,\n' 물체마다 상태(Sprite와 배열)가 있으며, 적은 시간표대로 나옵니다.\n' ← →로 움직이고 스페이스로 쏩니다. 키보드가 있는 데스크톱과 웹용입니다.\n\n' 적이 나오는 시간표의 한 줄: 몇 ms에, 몇 번째 길에, 어떤 적이.\nStructure Wave\n    At As Integer           ' 시작한 뒤 흐른 ms\n    Lane As Integer         ' 0부터 4까지, 왼쪽부터\n    Kind As Integer         ' 0: 느린 적, 1: 빠른 적\nEnd Structure\n\nConst Lanes As Integer = 5\nConst ShipSpeed As Double = 240     ' 초당 픽셀\nConst ShotSpeed As Double = -420\nConst FireGap As Integer = 220      ' 발사 사이의 ms\n\nDim shots(7) As Sprite\nDim enemies(19) As Sprite\nDim boomUntil(19) As Integer        ' 터지는 적이 사라질 때(ms); 0이면 터지는 중이 아님\nDim waves(23) As Wave\nDim nextWave As Integer\nDim startedAt As Integer\nDim lastTime As Integer\nDim lastShot As Integer\nDim score As Integer\nDim lives As Integer\n\nSub Form_Load()\n    Dim i As Integer\n    ' 탄과 적은 미리 만들어 두고, 쓸 때만 보입니다(Visible).\n    For i = 0 To UBound(shots)\n        shots(i) = New Sprite With {.Frames = \"shot.png\", .Width = 6, .Height = 14,\n                                    .Shape = \"Rectangle\", .SpeedY = ShotSpeed, .Visible = False}\n        Me.Controls.Add(shots(i))\n    Next\n    For i = 0 To UBound(enemies)\n        enemies(i) = New Sprite With {.Frames = \"enemy1.png, enemy2.png\", .FrameTime = 150,\n                                      .Width = 32, .Height = 32, .Shape = \"Circle\", .Visible = False}\n        Me.Controls.Add(enemies(i))\n    Next\n    ' 시간표: 처음에는 느린 적이 하나씩, 나중에는 빠른 적이 둘씩.\n    For i = 0 To 11\n        waves(i) = New Wave With {.At = 1000 + i * 1500, .Lane = (i * 3) Mod Lanes, .Kind = 0}\n    Next\n    For i = 12 To 23\n        waves(i) = New Wave With {.At = 19000 + (i - 12) * 900, .Lane = (i * 2 + 1) Mod Lanes, .Kind = 1}\n    Next\n    lblMessage.Caption = \"시작을 누르세요\"\nEnd Sub\n\nSub btnStart_Click()\n    Dim i As Integer\n    For i = 0 To UBound(shots)\n        shots(i).Visible = False\n    Next\n    For i = 0 To UBound(enemies)\n        enemies(i).Visible = False\n        boomUntil(i) = 0\n    Next\n    score = 0\n    lives = 3\n    nextWave = 0\n    sprShip.X = (Me.Width - sprShip.Width) / 2\n    sprShip.Visible = True\n    ShowStatus()\n    lblMessage.Caption = \"\"\n    btnStart.Enabled = False\n    ' 웹에서는 클릭 뒤에야 소리가 납니다: 시작 버튼이 그 클릭입니다.\n    Sound.PlayMusic(\"music.wav\")\n    startedAt = Milliseconds()\n    lastTime = startedAt\n    lastShot = 0\n    tmrGame.Start()\nEnd Sub\n\n' 게임 루프: 흐른 시간을 재고, 키를 읽고, 모두 움직이고, 부딪힘을 봅니다.\nSub tmrGame_Tick()\n    Dim now As Integer = Milliseconds()\n    Dim dt As Integer = now - lastTime\n    lastTime = now\n    Dim i As Integer\n    Dim j As Integer\n\n    ' 1. 우주선: 누른 키대로 속도를 정하고 움직입니다. 화면 밖으로는 못 갑니다.\n    sprShip.SpeedX = 0\n    If Keyboard.IsDown(Keys.Left) Then sprShip.SpeedX = -ShipSpeed\n    If Keyboard.IsDown(Keys.Right) Then sprShip.SpeedX = ShipSpeed\n    sprShip.Move(dt)\n    If sprShip.X < 0 Then sprShip.X = 0\n    If sprShip.X > Me.Width - sprShip.Width Then sprShip.X = Me.Width - sprShip.Width\n\n    ' 2. 발사: 스페이스를 누르고 있으면 FireGap마다 쉬는 탄 하나를 씁니다.\n    If Keyboard.IsDown(Keys.Space) And now - lastShot >= FireGap Then\n        For i = 0 To UBound(shots)\n            If Not shots(i).Visible Then\n                shots(i).X = sprShip.X + (sprShip.Width - shots(i).Width) / 2\n                shots(i).Y = sprShip.Y - shots(i).Height\n                shots(i).Visible = True\n                lastShot = now\n                Sound.Play(\"shot.wav\")\n                Exit For\n            End If\n        Next\n    End If\n\n    ' 3. 시간표: 때가 된 적을 내보냅니다.\n    Do While nextWave <= UBound(waves)\n        If now - startedAt < waves(nextWave).At Then Exit Do\n        Spawn(waves(nextWave))\n        nextWave = nextWave + 1\n    Loop\n\n    ' 4. 탄과 적을 움직입니다. 화면을 벗어난 탄은 쉬고, 벗어난 적은 목숨을 하나 뺏습니다.\n    For i = 0 To UBound(shots)\n        If shots(i).Visible Then\n            shots(i).Move(dt)\n            If shots(i).Y + shots(i).Height < 0 Then shots(i).Visible = False\n        End If\n    Next\n    For i = 0 To UBound(enemies)\n        If enemies(i).Visible Then\n            enemies(i).Move(dt)\n            If boomUntil(i) > 0 Then\n                If now >= boomUntil(i) Then\n                    enemies(i).Visible = False\n                    boomUntil(i) = 0\n                End If\n            ElseIf enemies(i).Y > Me.Height Then\n                enemies(i).Visible = False\n                LoseLife()\n            End If\n        End If\n    Next\n\n    ' 5. 부딪힘: 탄마다 적마다 Hits 한 번씩. 맞은 적은 터지는 그림으로 바뀝니다.\n    For i = 0 To UBound(shots)\n        If shots(i).Visible Then\n            For j = 0 To UBound(enemies)\n                If enemies(j).Visible And boomUntil(j) = 0 Then\n                    If shots(i).Hits(enemies(j)) Then\n                        shots(i).Visible = False\n                        Explode(j, now)\n                        score = score + 10\n                        ShowStatus()\n                        Exit For\n                    End If\n                End If\n            Next\n        End If\n    Next\n    For j = 0 To UBound(enemies)\n        If enemies(j).Visible And boomUntil(j) = 0 Then\n            If sprShip.Hits(enemies(j)) Then\n                Explode(j, now)\n                LoseLife()\n            End If\n        End If\n    Next\nEnd Sub\n\n' 시간표의 한 줄대로 쉬는 적 하나를 길 위에 내보냅니다.\nSub Spawn(wave As Wave)\n    Dim i As Integer\n    For i = 0 To UBound(enemies)\n        If Not enemies(i).Visible Then\n            Dim laneWidth As Double = Me.Width / Lanes\n            enemies(i).Frames = \"enemy1.png, enemy2.png\"\n            enemies(i).FrameTime = 150\n            enemies(i).X = wave.Lane * laneWidth + (laneWidth - enemies(i).Width) / 2\n            enemies(i).Y = -enemies(i).Height\n            enemies(i).SpeedY = 90 + wave.Kind * 70\n            enemies(i).Visible = True\n            boomUntil(i) = 0\n            Exit For\n        End If\n    Next\nEnd Sub\n\n' 적이 터집니다: 그림이 폭발로 바뀌고, 멈춘 채 잠시 뒤 사라집니다.\nSub Explode(index As Integer, now As Integer)\n    enemies(index).Frames = \"boom1.png, boom2.png, boom3.png\"\n    enemies(index).FrameTime = 80\n    enemies(index).SpeedY = 0\n    boomUntil(index) = now + 240\n    Sound.Play(\"hit.wav\")\nEnd Sub\n\nSub LoseLife()\n    lives = lives - 1\n    ShowStatus()\n    If lives <= 0 Then GameOver()\nEnd Sub\n\nSub GameOver()\n    tmrGame.Stop()\n    Sound.StopMusic()\n    sprShip.Visible = False\n    lblMessage.Caption = \"게임 끝: \" & score & \"점\"\n    btnStart.Caption = \"다시\"\n    btnStart.Enabled = True\nEnd Sub\n\nSub ShowStatus()\n    lblScore.Caption = \"점수 \" & score\n    lblLives.Caption = \"목숨 \" & lives\nEnd Sub\n",
    "Shooter.gbproj": "formatVersion: 4\nname: Shooter\nstartup: Form1\nforms:\n  - Form1\npictures:\n  - ship.png\n  - shot.png\n  - enemy1.png\n  - enemy2.png\n  - boom1.png\n  - boom2.png\n  - boom3.png\nsounds:\n  - shot.wav\n  - hit.wav\n  - music.wav\n",
  },
  "text": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Text\n  Width: 320\n  Height: 120\ncontrols:\n  - name: btnStart\n    type: Button\n    properties:\n      Caption: Start\n      Left: 8\n      Top: 8\n      Width: 96\n",
    "Form1.gbas": "' Benchmark 2 (STAGE2_PLAN §7): building and searching a long text.\nSub btnStart_Click()\n    Debug.Print(\"bench:start\")\n    Dim letters As String = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n    Dim s As String = \"\"\n    Dim i As Integer\n    For i = 0 To 1999\n        s = s & Mid(letters, i Mod 26 + 1, 1)\n    Next\n    Dim found As Integer = 0\n    For i = 1 To 1998\n        If InStr(s, Mid(s, i, 3)) > 0 Then\n            found = found + 1\n        End If\n    Next\n    Debug.Print(\"bench:end \" & found & \" \" & Len(s))\nEnd Sub\n",
    "Text.gbproj":
        "formatVersion: 1\nname: Text\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "typing": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Typing\n  Width: 320\n  Height: 160\ncontrols:\n  - name: txtName\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 16\n      Width: 288\n  - name: lblMessage\n    type: Label\n    properties:\n      Left: 16\n      Top: 60\n      Width: 288\n  - name: btnHello\n    type: Button\n    properties:\n      Caption: Say hello\n      Left: 16\n      Top: 100\n      Width: 120\n",
    "Form1.gbas": "' Typing in a TextBox: Changed runs each time the input method commits\n' a character (docs/LANGUAGE.md §11.1). Try it with a Korean input method.\nDim clickCount As Integer\n\nSub Form_Load()\n    lblMessage.Caption = \"Type your name, or press the button\"\nEnd Sub\n\nSub txtName_Changed()\n    lblMessage.Caption = \"Hello, \" & txtName.Text\nEnd Sub\n\nSub btnHello_Click()\n    clickCount = clickCount + 1\n    Dim name = txtName.Text\n    If name = \"\" Then\n        name = InputBox(\"What is your name?\")\n    End If\n    MsgBox(\"Hello, \" & name & \"! (\" & clickCount & \")\")\nEnd Sub\n",
    "Typing.gbproj":
        "formatVersion: 1\nname: Typing\nstartup: Form1\nforms:\n  - Form1\n",
  },
};

